@pytest.mark.parametrize("phase", ["prepare", "commit"]) @pytest.mark.parametrize("residual", ["app-output", "app-version", "run-result", "typed", "verified-operation"]) def test_failed_job_with_any_result_residue_enters_complete_verification(legacy_failure, phase, residual, monkeypatch): store, _, client, info = legacy_failure url, body = command(legacy_failure, phase) failed = info["failed_old_run_id"] with store.tx() as c: aid = c.execute(select(internal_run_bindings.c.app_run_id).where(internal_run_bindings.c.run_id == failed)).scalar_one() if residual == "app-output": c.execute(update(internal_app_runs).where(internal_app_runs.c.id == aid).values(output={"synthetic": "unexpected residual"})) elif residual == "app-version": c.execute(update(internal_app_runs).where(internal_app_runs.c.id == aid).values(result_version=99)) elif residual == "run-result": c.execute(update(runs).where(runs.c.id == failed).values(result={"synthetic": "unexpected residual"})) elif residual == "typed": row = dict(c.execute(select(internal_instance_data).where(internal_instance_data.c.instance_id == info["instance"]["id"])).mappings().one()) row.update(version=2, run_id=aid) c.execute(internal_instance_data.insert().values(**row)) c.execute(update(internal_instances).where(internal_instances.c.id == info["instance"]["id"]).values(data_version=2)) else: existing = c.execute(select(operations.c.id).where(operations.c.run_id == failed, operations.c.call_id == "instance_result")).scalar_one_or_none() if existing: c.execute(update(operations).where(operations.c.id == existing).values(status="VERIFIED")) else: op = dict(c.execute(select(operations).where(operations.c.run_id == info["successful_old_run_id"], operations.c.call_id == "instance_result")).mappings().one()) op.update(id=new_id("synthetic_verified_operation"), run_id=failed) c.execute(operations.insert().values(**op)) before = rows(store) calls = verifier_calls(monkeypatch) reply = client.post(url, json=body) after = rows(store) save(info, phase, residual, dict(response_status=reply.status_code, response=reply.json(), verified_jobs=calls, failed_job=failed, database_unchanged=after == before, fault="synthetic persisted residue; original old failed Worker had no typed result")) assert reply.status_code in {400, 409} and after == before, reply.text > assert failed in calls E AssertionError: assert 'run_19633a966dc34051a9d52a33518f7e1f' in []
